#!/bin/bash
set -euo pipefail

cd /app/src

# Add test data that exercises the return-with-non-nil-error skip.
# Bug: without isReturnedWithNonNilError, "return Params{}, errors.New(...)"
# incorrectly triggers "missing required fields: Name".
# Fix: the skip logic suppresses the error, so the test passes.
mkdir -p testdata/src/return_test
cat > testdata/src/return_test/return_test.go << 'EOF'
package return_test

import (
	"errors"
)

type Params struct { // want Params:"required<Name>"
	Name string // required
}

func makeErr() (Params, error) {
	return Params{}, errors.New("something failed") // ok
}

var errX = errors.New("x")

func makeNamedErr() (Params, error) {
	return Params{}, errX // ok
}

func makeNilErr() (Params, error) {
	return Params{}, nil // want "missing required fields: Name"
}

func makeErrorFirst() (error, Params) {
	return errors.New("x"), Params{} // want "missing required fields: Name"
}
EOF

# Run the analyzer test which exercises testdata/ via analysistest.Run
set +e
go test -v -count=1 -run TestAnalyzer ./...
test_status=$?
set -e

# Write reward
mkdir -p /logs/verifier
if [ $test_status -eq 0 ]; then
	echo 1 > /logs/verifier/reward.txt
else
	echo 0 > /logs/verifier/reward.txt
fi
exit 0

